func (n noListingFS) Open(name string) (http.File, error) {
	f, err := n.fs.Open(name)
	if err == nil {
		if st, serr := f.Stat(); serr == nil && st.IsDir() {
			f.Close()
			return nil, os.ErrNotExist // directories answer 404, never a listing
